// ============================================================
// POLITICAL ORGANIZATIONS & MACHINES
// ============================================================
// The apparatus between a leader and the people they rule: urban
// machines, dominant parties, cadre movements, palace guards and
// patronage networks. Organizations are first-class records here —
// like books — because one organization outlives and serves many
// leaders, and one leader may build one machine and fight another.
//
// Per-organization fields:
//   kind      machine | dominant | mass | cadre | court   (see ORG_KINDS)
//   from, to  years active (to: null = still operating)
//   end       how it ended (see ORG_ENDS)
//   linkage   clientelistic | programmatic | charismatic | cadre — how it bound supporters
//   s         { client, disc, reach, coerce } 0–100 estimates:
//             material exchange vs. programme · internal discipline ·
//             how far down it reached · use of force, fraud or intimidation
//   base      who it mobilised
//   currency  what it traded for support
//   chain     the brokerage chain from the top to the voter or subject
//   control   how it kept members and voters in line
//   revenue   where the money came from
//   ending    how and why it ended (or how it has survived)
//   lesson    the one thing it teaches
//   leaders   [{ id, rel, role }] — rel: built | led | made | used | fought
//   tags      concept keys from traits.js
//   books     library ids · reading: further citations
// All scores are my estimates.
// ============================================================

window.ORG_KINDS = [
  { key: "machine", name: "Urban & state machines", color: "var(--reg-loyalty)", def: "A party organisation that wins elections by trading concrete, individual benefits — jobs, favours, contracts, help with the landlord or the judge — for votes, through a hierarchy of bosses, ward leaders and precinct captains." },
  { key: "dominant", name: "Dominant & regime parties", color: "var(--reg-motivate)", def: "A party that holds power for decades — in a one-party state, or in a competitive system it has tilted — and doubles as the state's personnel office." },
  { key: "mass", name: "Mass & clientelist parties", color: "var(--reg-trust)", def: "Parties in competitive systems that built mass followings through unions, networks of brokers or a founding leader's charisma — and often ended up trading favours as much as programmes." },
  { key: "cadre", name: "Revolutionary & cadre organizations", color: "var(--reg-fear)", def: "Small, disciplined organisations built to take power rather than win elections: clubs, cells, conspiracies of officers, guerrilla movements." },
  { key: "court", name: "Courts, guards & patronage networks", color: "var(--era-medieval)", def: "The pre-modern machine: a ruler's household troops, court or network of clients — the organisation that stood between the ruler and everyone else before parties existed." }
];

